/**
 * AGEND-224 (upstream #3330 ruling): a NAMED Antigravity account's first-run files are GENERATED by an agent's launch, never copied from the default account's `~/.gemini`.
 *  - exactly what is written (an allow-list: settings.json → statusLine + trustedWorkspaces = this instance's own working directory; cache/onboarding.json → the known booleans);
 *  - only when the file is missing, never over one the account has, never through a link;
 *  - nothing of the default `~/.gemini` is read (made unreadable here, with markers that must not show up).
 */
import { chmodSync, existsSync, lstatSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, symlinkSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { FIRST_RUN_ONBOARDING, firstRunFiles, seedFirstRun } from "../src/antigravity-first-run.js";
import { AntigravityBackend } from "../src/backend/antigravity.js";
import { credentialHomeSpec, credentialProfileHome } from "../src/backend/credential-profile.js";

const dirs: string[] = [];
const scratch = () => { const d = mkdtempSync(join(tmpdir(), "agend-224-fr-")); dirs.push(d); return d; };
const saved = { gemini: process.env.GEMINI_HOME, agend: process.env.AGEND_HOME };
afterEach(() => {
  for (const d of dirs.splice(0)) { try { chmodSync(d, 0o700); } catch { /* gone */ } rmSync(d, { recursive: true, force: true }); }
  if (saved.gemini === undefined) delete process.env.GEMINI_HOME; else process.env.GEMINI_HOME = saved.gemini;
  if (saved.agend === undefined) delete process.env.AGEND_HOME; else process.env.AGEND_HOME = saved.agend;
});
const tree = (root: string, base = ""): string[] => readdirSync(join(root, base), { withFileTypes: true }).flatMap(e => e.isDirectory() ? tree(root, join(base, e.name)) : [join(base, e.name)]).sort();
const json = (path: string) => JSON.parse(readFileSync(path, "utf8"));
const CMD = "/agend/agy-statusline.sh";

describe("what is generated (pinned)", () => {
  it("settings.json: statusLine (AgEnD's own script, enabled) and trustedWorkspaces = [this instance's directory]; onboarding.json: the known booleans — nothing else", () => {
    expect(firstRunFiles("/work/dev", CMD)).toEqual({
      "settings.json": { statusLine: { command: CMD, enabled: true }, trustedWorkspaces: ["/work/dev"] },
      "cache/onboarding.json": { consumerOnboardingComplete: true, enterpriseOnboardingComplete: false, onboardingComplete: true },
    });
    expect(FIRST_RUN_ONBOARDING).toEqual({ consumerOnboardingComplete: true, enterpriseOnboardingComplete: false, onboardingComplete: true });
  });
  it("the spec has no copy list any more: nothing is seeded from the default account", () => {
    expect(credentialHomeSpec("antigravity")!.seed).toBeUndefined();
  });
});

describe("seedFirstRun writes only what is missing, only there", () => {
  it("a new folder gets exactly those two files (mode 0600), and returns their names", () => {
    const folder = scratch();
    expect(seedFirstRun(folder, "/work/dev", CMD).sort()).toEqual(["cache/onboarding.json", "settings.json"]);
    expect(tree(folder)).toEqual(["cache/onboarding.json", "settings.json"]);
    expect(lstatSync(join(folder, "settings.json")).mode & 0o777).toBe(0o600);
    expect(json(join(folder, "settings.json")).trustedWorkspaces).toEqual(["/work/dev"]);
  });
  it("a file the account already has is left exactly as it is (agy's own, or an earlier launch's), and the other is still written", () => {
    const folder = scratch();
    writeFileSync(join(folder, "settings.json"), JSON.stringify({ model: "mine", trustedWorkspaces: ["/kept"] }));
    expect(seedFirstRun(folder, "/work/dev", CMD)).toEqual(["cache/onboarding.json"]);
    expect(json(join(folder, "settings.json"))).toEqual({ model: "mine", trustedWorkspaces: ["/kept"] });
    expect(seedFirstRun(folder, "/other/dir", CMD), "a second launch writes nothing").toEqual([]);
    expect(json(join(folder, "cache", "onboarding.json"))).toEqual({ ...FIRST_RUN_ONBOARDING });
  });
  it("never through a link: a symlink (even a dangling one) where a file belongs, or where `cache` belongs, is not written through", () => {
    const folder = scratch(), elsewhere = scratch();
    symlinkSync(join(elsewhere, "target.json"), join(folder, "settings.json"));       // dangling
    symlinkSync(elsewhere, join(folder, "cache"));
    expect(seedFirstRun(folder, "/work/dev", CMD)).toEqual([]);
    expect(readdirSync(elsewhere), "nothing was created behind the links").toEqual([]);
  });
  it("a working directory that is not one absolute path writes nothing (a trust entry names one directory)", () => {
    for (const bad of ["", "relative/dir", "/a\nb", "/a\0b", "/" + "x".repeat(5000)]) {
      const folder = scratch();
      expect(seedFirstRun(folder, bad, CMD), JSON.stringify(bad).slice(0, 30)).toEqual([]);
      expect(readdirSync(folder)).toEqual([]);
    }
  });
});

describe("an agent's launch on a named account (AntigravityBackend)", () => {
  function world() {
    const data = scratch(), userHome = scratch(), gemini = join(userHome, ".gemini"), def = join(gemini, "antigravity-cli");
    mkdirSync(join(def, "cache"), { recursive: true });
    writeFileSync(join(def, "settings.json"), JSON.stringify({ trustedWorkspaces: ["/DEFAULT-ONLY-MARKER"], statusLine: { command: "/DEFAULT-ONLY-MARKER/line.sh", enabled: true }, model: "DEFAULT-ONLY-MARKER" }));
    writeFileSync(join(def, "cache", "onboarding.json"), JSON.stringify({ onboardingComplete: true, marker: "DEFAULT-ONLY-MARKER" }));
    writeFileSync(join(def, "antigravity-oauth-token"), JSON.stringify({ token: { access_token: "DEFAULT-ONLY-MARKER" } }));
    process.env.GEMINI_HOME = gemini; process.env.AGEND_HOME = data;
    return { data, userHome, gemini, def, account: (name: string) => credentialProfileHome(data, "antigravity", name) };
  }
  const start = (w: ReturnType<typeof world>, name: string, workdir: string) => {
    mkdirSync(workdir, { recursive: true });
    const instanceDir = join(w.data, "instances", name); mkdirSync(instanceDir, { recursive: true });
    const be = new AntigravityBackend(instanceDir, w.userHome, w.data);
    (be as unknown as { binaryPath: string }).binaryPath = "/usr/bin/agy";
    const config = { workingDirectory: workdir, instanceDir, instanceName: name, mcpServers: {}, backendOptions: { credential_profile: "work" } } as never;
    const command = be.buildCommand(config); be.writeConfig(config);
    return command;
  }

  it("the account's folder gets the generated files with ONLY this instance's directory trusted, AgEnD's own status line, and no word of the default account's files", () => {
    const w = world(), wd = join(scratch(), "workspace-dev");
    start(w, "dev", wd);
    const folder = w.account("work");
    expect(tree(folder)).toEqual(["cache/onboarding.json", "settings.json"]);
    const settings = json(join(folder, "settings.json"));
    expect(settings.trustedWorkspaces).toEqual([wd]);
    expect(settings.statusLine).toEqual({ command: join(w.data, "agy-statusline.sh"), enabled: true });
    expect(Object.keys(settings).sort()).toEqual(["statusLine", "trustedWorkspaces"]);
    expect(json(join(folder, "cache", "onboarding.json"))).toEqual({ ...FIRST_RUN_ONBOARDING });
    for (const name of tree(folder)) expect(readFileSync(join(folder, name), "utf8"), name).not.toContain("DEFAULT-ONLY-MARKER");
    expect(existsSync(join(folder, "antigravity-oauth-token"))).toBe(false);
  });
  it("it reads NOTHING under the default ~/.gemini: made unreadable, the launch still works and gives the same files", () => {
    const w = world();
    chmodSync(w.gemini, 0o000);                                                  // a read of anything below it would fail (a no-op for root, where the markers above still prove it)
    try { start(w, "dev", join(scratch(), "ws")); } finally { chmodSync(w.gemini, 0o700); }
    expect(tree(w.account("work"))).toEqual(["cache/onboarding.json", "settings.json"]);
    expect(JSON.parse(readFileSync(join(w.def, "settings.json"), "utf8")).trustedWorkspaces, "the default's own files are untouched").toEqual(["/DEFAULT-ONLY-MARKER"]);
  });
  it("a second instance on the same account does not widen the trust: the account's settings.json exists, so it is left as it is", () => {
    const w = world(), a = join(scratch(), "a"), b = join(scratch(), "b");
    start(w, "one", a); start(w, "two", b);
    expect(json(join(w.account("work"), "settings.json")).trustedWorkspaces).toEqual([a]);
  });
  it("the default sign-in's launch (no account) generates nothing and touches no account folder", () => {
    const w = world();
    const instanceDir = join(w.data, "instances", "plain"); mkdirSync(instanceDir, { recursive: true });
    const be = new AntigravityBackend(instanceDir, w.userHome, w.data);
    (be as unknown as { binaryPath: string }).binaryPath = "/usr/bin/agy";
    be.buildCommand({ workingDirectory: instanceDir, instanceDir, instanceName: "plain", mcpServers: {} } as never);
    expect(existsSync(join(w.data, "credential-profiles"))).toBe(false);
  });
});
